'use strict';
let currentUser=null,currentTenant=null,products=[],cart=[],tab='dashboard',orders=[],pendingTransaction=null;
let visibleProductRows=60,visibleCashierCards=48,navGeneration=0,transactionBusy=false;
const lookups={products:{q:'',items:null,cursor:null,token:0,timer:null,loading:false},cashier:{q:'',items:null,cursor:null,token:0,timer:null,loading:false}};
function cancelLookups(){for(const state of Object.values(lookups)){clearTimeout(state.timer);state.token++;state.q='';state.items=null;state.cursor=null;state.loading=false;}}
function mergeCatalog(items){const known=new Set(products.map(p=>p.id));for(const p of items){if(!known.has(p.id)){products.push(p);known.add(p.id)}}}
function startLookup(kind,q){const st=lookups[kind];clearTimeout(st.timer);const token=++st.token;st.q=q;st.items=null;st.cursor=null;st.loading=false;
 const paint=kind==='products'?paintProductRows:paintCashier;paint();if(!q.trim())return;
 st.timer=setTimeout(async()=>{try{st.loading=true;const result=await api('/products?limit=60&q='+encodeURIComponent(q));if(token!==st.token)return;st.items=result.items;st.cursor=result.nextCursor;mergeCatalog(result.items);paint()}catch(e){if(token===st.token)message('Pencarian server gagal: '+e.message,true)}finally{if(token===st.token)st.loading=false}},240);
}
async function moreLookup(kind){const st=lookups[kind];if(!st.cursor||st.loading)return;const token=st.token;const cursor=st.cursor;st.loading=true;try{const data=await api('/products?limit=60&q='+encodeURIComponent(st.q)+'&cursor='+encodeURIComponent(cursor));if(token!==st.token)return;st.items.push(...data.items);st.cursor=data.nextCursor;mergeCatalog(data.items);if(kind==='products')visibleProductRows+=60;else visibleCashierCards+=60;(kind==='products'?paintProductRows:paintCashier)();}catch(e){if(token===st.token)message(e.message,true)}finally{if(token===st.token)st.loading=false}}

const labels={dashboard:'Dashboard',sales:'Penjualan',purchases:'Pembelian',products:'Produk & Stok',orders:'Pesanan Web Toko',reports:'Laporan',billing:'Langganan & Pajak',employees:'Karyawan'};
const $screen=$('screen'),notice=$('notice');
function menuList(){return Object.keys(labels).filter(k=>k!=='employees'||currentUser?.role==='OWNER');}
function setNav(){const html=menuList().map(k=>`<button class="navbtn ${tab===k?'active':''}" data-tab="${k}">${labels[k]}</button>`).join('');$('menu').innerHTML=html;$('mobileNav').innerHTML=[['dashboard','Home'],['orders','Pesanan'],['sales','Transaksi Baru'],['reports','Laporan'],['more','Menu']].map(([k,label])=>`<button class="navbtn ${tab===k?'active':''}" ${k==='more'?'id="moreNav"':`data-tab="${k}"`}>${label}</button>`).join('');
 $('mobileMore').innerHTML=menuList().map(k=>`<button class="navbtn" data-tab="${k}">${labels[k]}</button>`).join('');
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
 $('moreNav').onclick=()=>{$('mobileMore').classList.toggle('hidden');};}
async function init(){try{const me=await api('/auth/me');onLogin(me);}catch{$('authPage').classList.remove('hidden');$('appPage').classList.add('hidden');}}
function requirePinChange(){
 $('authPage').classList.remove('hidden');$('appPage').classList.add('hidden');
 $('loginForm').classList.add('hidden');$('registerForm').classList.add('hidden');$('toggleAuth').classList.add('hidden');
 $('changePinForm').classList.remove('hidden');$('authHeading').textContent='Ganti PIN Awal';
}
function onLogin(result){if(result.user?.role==='SUPER_ADMIN'){notify($('authMessage'),'Akun Super Admin hanya dapat menggunakan adms.inpos.id',true);return;}if(result.user?.mustChangePin){requirePinChange();return;}$('loginForm').classList.remove('hidden');$('changePinForm').classList.add('hidden');$('toggleAuth').classList.remove('hidden');currentUser=result.user;currentTenant=result.tenant;cart=[];$('authPage').classList.add('hidden');$('appPage').classList.remove('hidden');$('currentStore').textContent=currentTenant?.name||'Kasir';$('whoami').textContent=`${currentUser.displayName} · ${currentUser.role}`;switchTab('dashboard');}
function message(s,error=false){notify(notice,s,error);}
function errorHandler(e){message(e.message,true);}
async function switchTab(k){if(transactionBusy){message('Selesaikan proses transaksi sebelum berpindah menu',true);return;}
 const generation=++navGeneration;cancelLookups();$('mobileMore').classList.add('hidden');tab=k;setNav();$('sectionTitle').textContent=labels[k];$('sectionSub').textContent='Data toko: '+currentTenant?.name;message('');try{
 if(['dashboard','sales','purchases','products'].includes(k)){const list=await api('/products');if(generation!==navGeneration)return;products=list;}
 if(k==='orders'){const list=await api('/orders');if(generation!==navGeneration)return;orders=list;}
 if(generation!==navGeneration)return;
 if(k==='dashboard'){const status=currentTenant?.status||'-';const deadline=currentTenant?.status==='TRIAL'?currentTenant?.trialEndsAt:currentTenant?.subscriptionEndsAt;const active=deadline&&new Date(deadline)>new Date()&&status!=='SUSPENDED';$('tenantState').textContent=active?status:'Perlu perpanjangan';renderDashboard();}
 if(k==='products')renderProducts();if(k==='sales'||k==='purchases'){cart=[];renderCashier();}if(k==='orders')renderOrders();
 if(k==='reports')await renderReports(generation);if(k==='billing')await renderBilling(generation);if(k==='employees')await renderEmployees(generation);
 }catch(e){if(generation===navGeneration)errorHandler(e)}}
function renderDashboard(){const low=products.filter(p=>p.active&&p.stock<=p.minStock).length;
$screen.innerHTML=`<div class="stats"><div class="stat"><span>Produk dimuat</span><b>${products.length}</b></div><div class="stat"><span>Stok menipis (dimuat)</span><b>${low}</b></div><div class="stat"><span>Peran Akun</span><b style="font-size:17px">${esc(currentUser.role)}</b></div></div><div class="card"><h2>Mulai operasional</h2><p class="sub">Gunakan menu Penjualan atau Pembelian untuk mencatat mutasi stok. Semua transaksi dikirim ke API sesuai toko yang sedang login.</p><div class="toolbar"><button class="btn red" id="goSale">Transaksi Baru</button><button class="btn" id="goProduct">Kelola Produk</button></div><small class="muted">Aplikasi ini modul operasional dasar. Fitur lengkap INPOS HTML lama disimpan terpisah untuk migrasi bertahap.</small></div>`;
$('goSale').onclick=()=>switchTab('sales');$('goProduct').onclick=()=>switchTab('products');}
function renderProducts(){const owner=currentUser.role==='OWNER';$screen.innerHTML=`<div class="card"><div class="toolbar"><input id="productSearch" class="search-input" placeholder="Cari nama / SKU produk"><button id="addProduct" class="btn red">+ Produk</button></div><div id="productTable"></div></div><div id="productFormWrap"></div>`;
visibleProductRows=60;$('productSearch').oninput=()=>{visibleProductRows=60;startLookup('products',$('productSearch').value.trim().toLowerCase())};$('addProduct').onclick=()=>productForm();paintProductRows();}
function paintProductRows(){const owner=currentUser?.role==='OWNER';const q=$('productSearch')?.value.toLowerCase()||'';const st=lookups.products;const rows=st.items&&st.q===q?st.items:products.filter(p=>(p.name+' '+p.sku+' '+p.category).toLowerCase().includes(q));$('productTable').innerHTML=`<div class="table-scroll"><table class="table"><thead><tr><th>Produk</th><th>Satuan</th><th>Stok</th><th>Harga</th><th>Aksi</th></tr></thead><tbody>${rows.slice(0,visibleProductRows).map(p=>`<tr><td><b>${esc(p.name)}</b> ${p.active?'':'<span class="pill warn">Nonaktif</span>'}<br><small class="muted">${esc(p.sku)} · ${esc(p.category)}</small></td><td>${esc(p.baseUnit)}${p.packUnit?`<br><small>1 ${esc(p.packUnit)} = ${p.packFactor} ${esc(p.baseUnit)}</small>`:''}</td><td>${p.stock}</td><td>${fmt(p.price)}</td><td>${owner?`<button class="btn small" data-edit="${p.id}">Edit</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>${rows.length>visibleProductRows||st.items&&st.cursor?`<div class="toolbar"><button class="btn" id="showMoreProducts" type="button">Tampilkan lainnya</button></div>`:''}${!q&&products.length>=500?'<p class="sub">Daftar awal maksimal 500 produk. Ketik nama atau SKU untuk mencari produk lain langsung dari server.</p>':''}`;
$('showMoreProducts')?.addEventListener('click',()=>{if(st.items&&rows.length<=visibleProductRows&&st.cursor){void moreLookup('products')}else{visibleProductRows+=60;paintProductRows()}});
document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(products.find(p=>p.id===b.dataset.edit)));}
function productForm(p){const edit=!!p;$('productFormWrap').innerHTML=`<div class="card"><h2>${edit?'Edit Produk':'Tambah Produk'}</h2><form id="productForm" class="form-grid stack"><label>Nama Produk<input name="name" required value="${esc(p?.name||'')}"></label><label>SKU / Barcode<input name="sku" required value="${esc(p?.sku||'')}"></label><label>Kategori<input name="category" value="${esc(p?.category||'Umum')}"></label><label>Satuan Dasar<input name="baseUnit" value="${esc(p?.baseUnit||'pcs')}"></label><label>Satuan Kemasan<input name="packUnit" placeholder="Box / Dus" value="${esc(p?.packUnit||'')}"></label><label>Isi kemasan (konversi ke satuan dasar)<input name="packFactor" type="number" min="1" value="${p?.packFactor||1}"></label><label>Harga Jual / Ecer (Rp)<input name="price" type="number" required min="0" value="${p?.price||0}"></label><label>Harga Modal / Ecer (Rp)<input name="cost" type="number" min="0" value="${p?.cost||0}"></label><label>Minimal Stok<input name="minStock" type="number" min="0" value="${p?.minStock||0}"></label>${!edit?`<label>Stok Awal<input name="stock" type="number" min="0" value="0"></label>`:''}<label class="full" style="display:flex;align-items:center;gap:10px"><input name="active" type="checkbox" style="width:auto" ${p?.active!==false?'checked':''}> Produk aktif / tampil di kasir & Web Toko</label><div class="toolbar full"><button class="btn red" type="submit">Simpan</button><button class="btn" id="cancelProduct" type="button">Batal</button></div></form></div>`;
$('cancelProduct').onclick=()=>$('productFormWrap').innerHTML='';$('productForm').onsubmit=async e=>{e.preventDefault();const d=formData(e.target);const payload={name:d.name,sku:d.sku,category:d.category,baseUnit:d.baseUnit,packUnit:d.packUnit||undefined,packFactor:Number(d.packFactor),price:Number(d.price),cost:Number(d.cost),minStock:Number(d.minStock),active:e.target.elements.active.checked};if(!edit)payload.stock=Number(d.stock);try{await api('/products'+(edit?'/'+p.id:''),edit?'PATCH':'POST',payload);products=await api('/products');$('productFormWrap').innerHTML='';startLookup('products',$('productSearch')?.value.trim().toLowerCase()||'');message('Produk berhasil disimpan');}catch(err){errorHandler(err)}};
}
function renderCashier(){const sale=tab==='sales';$screen.innerHTML=`<div class="store-layout"><section><div class="toolbar"><input class="search-input" id="cashierSearch" placeholder="Cari produk / SKU..." aria-label="Cari Produk"></div><div class="product-grid" id="cashierGrid"></div></section><aside class="cart"><h2>Keranjang ${sale?'Penjualan':'Pembelian'}</h2><div id="cartLines"></div><div class="summary">Total <strong id="cartTotal">Rp 0</strong></div><button id="checkout" class="btn red" style="width:100%">${sale?'Simpan Penjualan':'Simpan Pembelian'}</button><p class="muted-small">Qty dihitung dalam satuan dasar. Transaksi tersimpan melalui API.</p></aside></div>`;
visibleCashierCards=48;$('cashierSearch').oninput=()=>{visibleCashierCards=48;startLookup('cashier',$('cashierSearch').value.trim().toLowerCase())}; $('checkout').onclick=saveTransaction;paintCashier();paintCart();}
function paintCashier(){const q=$('cashierSearch').value.toLowerCase();const st=lookups.cashier;const source=st.items&&st.q===q?st.items:products;const matches=source.filter(p=>p.active&&(tab==='purchases'||p.stock>0)&&(p.name+' '+p.sku).toLowerCase().includes(q));$('cashierGrid').innerHTML=matches.slice(0,visibleCashierCards).map(p=>`<article class="product-card"><strong>${esc(p.name)}</strong><small>${esc(p.category)} · Stok ${p.stock} ${esc(p.baseUnit)}</small><b>${fmt(tab==='sales'?p.price:p.cost)}</b><button class="btn small" data-add="${p.id}">+ Tambah</button></article>`).join('')+(matches.length>visibleCashierCards||st.items&&st.cursor?`<button class="btn" id="showMoreCashier" type="button">Tampilkan lainnya</button>`:'');$('showMoreCashier')?.addEventListener('click',()=>{if(st.items&&matches.length<=visibleCashierCards&&st.cursor){void moreLookup('cashier')}else{visibleCashierCards+=48;paintCashier()}});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const p=products.find(x=>x.id===b.dataset.add);const old=cart.find(x=>x.id===p.id);if(tab==='sales'&&old&&old.qty>=p.stock)return message('Stok produk tidak mencukupi',true);if(old)old.qty++;else cart.push({id:p.id,qty:1});paintCart()});}
function paintCart(){const sale=tab==='sales';let total=0;$('cartLines').innerHTML=cart.length?cart.map(x=>{const p=products.find(v=>v.id===x.id);const price=sale?p.price:p.cost;total+=price*x.qty;return `<div class="line-item"><div><strong>${esc(p.name)}</strong><div class="muted-small">${fmt(price)} × ${x.qty}</div></div><div class="qty-control"><button data-less="${p.id}">−</button><b>${x.qty}</b><button data-more="${p.id}">+</button></div></div>`;}).join(''):'<div class="empty">Belum ada item</div>';$('cartTotal').textContent=fmt(total);document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{const row=cart.find(x=>x.id===b.dataset.more),p=products.find(x=>x.id===row.id);if(tab==='sales'&&row.qty>=p.stock)return message('Stok produk tidak mencukupi',true);row.qty++;paintCart()});document.querySelectorAll('[data-less]').forEach(b=>b.onclick=()=>{const x=cart.find(x=>x.id===b.dataset.less);x.qty--;cart=cart.filter(v=>v.qty>0);paintCart()});}
async function saveTransaction(){if(transactionBusy)return;if(!cart.length)return message('Pilih produk terlebih dahulu',true);transactionBusy=true;const btn=$('checkout');btn.disabled=true;const kind=tab;const lines=cart.map(x=>({productId:x.id,qty:x.qty}));const signature=JSON.stringify({kind,lines});
 if(!pendingTransaction||pendingTransaction.signature!==signature)pendingTransaction={signature,requestId:newRequestId()};
 try{const result=await api('/transactions/'+(kind==='sales'?'sales':'purchases'),'POST',{requestId:pendingTransaction.requestId,lines});pendingTransaction=null;cart=[];message('Transaksi berhasil dicatat · '+fmt(result.total));try{const updated=await api('/products');if(tab===kind){products=updated;cancelLookups();renderCashier();}}catch(error){errorHandler(error)}}catch(e){errorHandler(e)}finally{transactionBusy=false;if($('checkout'))$('checkout').disabled=false;}}
async function renderReports(generation){const [sales,purchases,summary]=await Promise.all([api('/transactions/sales'),api('/transactions/purchases'),api('/transactions/summary')]);if(generation!==navGeneration)return;
 const totalSales=summary.sales.total,totalPurchases=summary.purchases.total;
 $screen.innerHTML=`<div class="card"><h2>Laporan Ringkas</h2><p class="sub">Ringkasan total seluruh transaksi yang telah tersimpan; tabel di bawah menampilkan maksimal 50 transaksi terbaru per jenis. Pesanan Web Toko yang dikonfirmasi belum termasuk penjualan.</p><div class="stats"><div class="stat"><span>Penjualan (${summary.sales.count} transaksi)</span><b>${fmt(totalSales)}</b></div><div class="stat"><span>Pembelian (${summary.purchases.count} transaksi)</span><b>${fmt(totalPurchases)}</b></div></div></div><div class="card"><h2>Transaksi Terbaru</h2><div class="table-scroll"><table class="table"><thead><tr><th>Jenis</th><th>Waktu</th><th>Nominal</th></tr></thead><tbody>${[...sales.map(t=>({...t,type:'Penjualan'})),...purchases.map(t=>({...t,type:'Pembelian'}))].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,50).map(t=>`<tr><td>${t.type}</td><td>${new Date(t.createdAt).toLocaleString('id-ID')}</td><td>${fmt(t.total)}</td></tr>`).join('')||'<tr><td colspan="3">Belum ada transaksi.</td></tr>'}</tbody></table></div></div>`;
}
function renderOrders(){$screen.innerHTML=`<div class="card"><h2>Pesanan Masuk</h2><p class="sub">Konfirmasi pesanan mengurangi stok. Pembayaran belum otomatis diverifikasi.</p><div class="table-scroll"><table class="table"><thead><tr><th>Pelanggan</th><th>Pesanan</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${esc(o.customer)}</b><br><small>${esc(o.phone)}</small></td><td>${o.items.map(i=>esc(i.product.name)+' × '+i.qty).join('<br>')}</td><td>${fmt(o.total)}</td><td>${esc(o.status)}</td><td>${o.status==='PENDING'?`<button class="btn small" data-confirm="${o.id}">Terima</button><button class="btn small danger" data-reject="${o.id}">Tolak</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></div>`;document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>resolveOrder(b.dataset.confirm,'confirm'));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>resolveOrder(b.dataset.reject,'reject'));}
async function resolveOrder(id,action){if(!confirm(action==='confirm'?'Konfirmasi pesanan dan kurangi stok?':'Tolak pesanan?'))return;try{await api('/orders/'+id+'/'+action,'POST',{});orders=await api('/orders');renderOrders();message('Pesanan diperbarui')}catch(e){errorHandler(e)}}
async function renderBilling(generation){const [c,rows]=await Promise.all([api('/billing/config'),api('/billing/my-invoices')]);if(generation!==navGeneration)return;$screen.innerHTML=`<div class="card"><h2>Langganan INPOS & Modul Pajak</h2><p class="sub">Tagihan harus diverifikasi manual oleh Super Admin. Aktivasi Pajak tidak otomatis membuka fitur pelaporan yang belum dimigrasikan.</p><div class="stats"><div class="stat"><span>Langganan / bulan</span><b>${fmt(c.subscriptionPrice)}</b></div><div class="stat"><span>Lisensi Pajak / bulan</span><b>${fmt(c.taxLicensePrice)}</b></div></div><form id="invoiceForm" class="form-grid stack"><label>Jenis tagihan<select name="type"><option value="SUBSCRIPTION">Langganan INPOS</option><option value="TAX">Lisensi Pajak</option></select></label><label>Jumlah bulan<input name="months" type="number" min="1" max="24" value="1" required></label><div class="full"><button class="btn red">Buat Tagihan QRIS</button></div></form><div id="invoiceResult"></div></div><div class="card"><h2>Riwayat Tagihan</h2><div class="table-scroll"><table class="table"><tbody>${rows.map(p=>`<tr><td>${esc(p.type)} · ${p.months} bulan</td><td>${fmt(p.total)} <small>(${String(p.uniqueCode).padStart(3,'0')})</small></td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table></div></div>`;
$('invoiceForm').onsubmit=async e=>{e.preventDefault();const d=formData(e.target);try{const p=await api('/billing/request','POST',{type:d.type,months:Number(d.months)});if(!$('invoiceResult'))return;$('invoiceResult').innerHTML=`<div class="card"><h2>Total Bayar ${fmt(p.total)}</h2><p>Nominal ${fmt(p.amount)} + Kode Unik ${String(p.uniqueCode).padStart(3,'0')}</p>${p.qrisImageUrl?`<img src="${esc(p.qrisImageUrl)}" alt="QRIS resmi Super Admin" style="max-width:220px;width:100%">`:''}<p class="sub">Tagihan menunggu validasi Super Admin.</p></div>`;message('Tagihan diterbitkan.');}catch(err){errorHandler(err)}};}
async function renderEmployees(generation){const list=await api('/employees');if(generation!==undefined&&generation!==navGeneration)return;$screen.innerHTML=`<div class="card"><h2>Tambah Karyawan</h2><form id="employeeForm" class="form-grid stack"><label>Nama Karyawan<input name="displayName" required></label><label>Username<input name="username" required></label><label>PIN Karyawan (6 digit)<input type="password" name="password" minlength="6" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" required></label><div><button class="btn red">Tambah Karyawan</button></div></form></div><div class="card"><h2>Daftar Karyawan</h2>${list.map(u=>`<div class="line-item"><strong>${esc(u.displayName)}</strong><span>${esc(u.username)} · ${u.active?'Aktif':'Nonaktif'}</span></div>`).join('')}</div>`;$('employeeForm').onsubmit=async e=>{e.preventDefault();try{await api('/employees','POST',formData(e.target));message('Karyawan berhasil dibuat');await renderEmployees()}catch(err){errorHandler(err)}};}
$('changePinForm').onsubmit=async e=>{e.preventDefault();try{
 await api('/auth/change-pin','POST',formData(e.target));$('changePinForm').classList.add('hidden');$('toggleAuth').classList.remove('hidden');
 onLogin(await api('/auth/me'));
 }catch(err){notify($('authMessage'),err.message,true)}};
$('toggleAuth').onclick=()=>{const reg=$('registerForm').classList.contains('hidden');$('registerForm').classList.toggle('hidden',!reg);$('loginForm').classList.toggle('hidden',reg);$('authHeading').textContent=reg?'Registrasi Owner':'Masuk INPOS';$('toggleAuth').textContent=reg?'Sudah punya akun? Login':'Belum punya akun? Registrasi';};
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const data=await api('/auth/login','POST',formData(e.target));notify($('authMessage'),'');onLogin(data);}catch(err){notify($('authMessage'),err.message,true)}};
$('registerForm').onsubmit=async e=>{e.preventDefault();try{const d=formData(e.target);const data=await api('/auth/register','POST',d);onLogin(data)}catch(err){notify($('authMessage'),err.message,true)}};
$('logout').onclick=async()=>{if(transactionBusy)return message('Transaksi sedang diproses',true);try{await api('/auth/logout','POST',{});}catch(e){return message('Logout gagal: '+e.message,true)}navGeneration++;cancelLookups();csrf='';currentUser=null;pendingTransaction=null;$('appPage').classList.add('hidden');$('authPage').classList.remove('hidden');$('loginForm').classList.remove('hidden');$('registerForm').classList.add('hidden');$('changePinForm').classList.add('hidden');$('toggleAuth').classList.remove('hidden');$('authHeading').textContent='Masuk INPOS';};
init();
